import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE customers(id INT, name TEXT);
CREATE TABLE orders(id INT, customer_id INT);
INSERT INTO customers VALUES(1,'Ann'),(2,'Bob'),(3,'Cy');
INSERT INTO orders VALUES(10,1),(11,1),(12,1),(13,2);
CREATE TABLE t(a INT, b INT);
INSERT INTO t VALUES(1,NULL),(1,NULL),(1,2),(1,2);
""")
def show(label, sql):
    print(f"{label:<18}", db.execute(sql).fetchall())

# DISTINCT compares the whole row and treats NULL = NULL
show("DISTINCT a, b", "SELECT DISTINCT a, b FROM t")
# A join fans out: Ann appears once per order
show("join (fan-out)", "SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id")
# Smell: DISTINCT hides the fan-out
show("DISTINCT hides it", "SELECT DISTINCT c.name FROM customers c JOIN orders o ON o.customer_id = c.id")
# Better: say what you mean ("has at least one order")
show("EXISTS", "SELECT name FROM customers c WHERE EXISTS "
               "(SELECT 1 FROM orders o WHERE o.customer_id = c.id)")
show("GROUP BY count", "SELECT c.name, COUNT(*) FROM customers c JOIN orders o "
                       "ON o.customer_id = c.id GROUP BY c.name")

import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE products(id INTEGER PRIMARY KEY, name TEXT, brand TEXT, price INT);
INSERT INTO products(name, brand, price) VALUES
 ('Red Pen','Acme',3),('Blue Pen','Acme',3),('Red Pad','Bolt',9),
 ('Pen Case','Bolt',12),('Green Pen',NULL,5),('Gel Pen','Acme',7);
""")
SORTS = {"price": "price", "name": "name"}          # whitelist of sort columns

def search(text=None, brand=None, max_price=None, sort="price", after=None, size=2):
    where, args = [], []                             # only ? placeholders carry user data
    if text:
        where.append("name LIKE ? ESCAPE '\\'")
        args.append("%" + text.replace("%", "\\%").replace("_", "\\_") + "%")
    if brand:
        where.append("brand = ?"); args.append(brand)
    if max_price is not None:
        where.append("price <= ?"); args.append(max_price)
    col = SORTS[sort]                                # KeyError if not whitelisted
    if after:                                        # keyset cursor (sort key, id)
        where.append(f"({col}, id) > (?, ?)"); args += after
    sql = "SELECT id, name, price FROM products"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += f" ORDER BY {col}, id LIMIT ?"            # id is the tie-breaker
    return db.execute(sql, args + [size]).fetchall()

p1 = search(text="pen")
print("page 1:", p1)
print("page 2:", search(text="pen", after=(p1[-1][2], p1[-1][0])))
print("brand Acme <= 5:", search(brand="Acme", max_price=5))
